"""Matched final-score comparison of observed-gap context modes.

All frozen supervision rows, including unsupported learned rule fallback, remain
included. Calibration selects thresholds before test metrics. This reused cohort
measures reference support, not biological accuracy; unconfirmed is not a proven
negative. Sparse gap-linked supervision and reference overlap prevent claims of
missing-enzyme recovery or unseen-family generalization. No model is promoted.
"""
import argparse
from collections import Counter
import csv
import json
from pathlib import Path

import analyze_observed_gap_models as A
import run_observed_gap_context_modes as R
F = R.F
KINDS = ('rule',) + tuple(F.KINDS)
ARMS = tuple(f'{mode}/{kind}' for mode in R.MODES for kind in KINDS)
POLICY = dict(schema='gspa.observed-gap-context-comparison/1', scope=__doc__,
    arms=list(ARMS), thresholds=A.POLICY['thresholds'],
    population=A.POLICY['population'], bootstrap=A.POLICY['bootstrap'],
    uncertainty=A.POLICY['uncertainty'],
    comparisons='Each restricted context against UNIVERSAL with the same scorer; each learned scorer against rules within the same context.')


def attach_scores(rows, by_arm):
    if set(by_arm) != set(ARMS):
        raise ValueError('missing or unexpected comparison arm')
    result = []; seen = set()
    for row in rows:
        if row['split'] not in F.T.SPLITS:
            raise ValueError('unknown split')
        if type(row['label']) is not int or row['label'] not in (0, 1):
            raise ValueError('invalid label')
        gid = row['genome_id']; key = A.function_key(row)
        if (gid, key) in seen:
            raise ValueError('duplicate supervised function identity')
        seen.add((gid, key)); scores = {}
        for arm in ARMS:
            if gid not in by_arm[arm] or key not in by_arm[arm][gid]:
                raise ValueError('missing supervised prediction')
            scores[arm] = A.probability(by_arm[arm][gid][key])
        result.append(dict(example_id=row['example_id'], genome_id=gid,
            split=row['split'], label=row['label'], label_basis=row['label_basis'],
            scores=scores))
    return result


def select_thresholds(rows):
    if not rows or any(r['split'] != 'calibration' for r in rows):
        raise ValueError('threshold selection requires calibration rows only')
    if {r['label'] for r in rows} != {0, 1}:
        raise ValueError('both calibration classes required')
    return {arm: F.T.choose_threshold(F.T.np.asarray([r['scores'][arm] for r in rows]),
        F.T.np.asarray([r['label'] for r in rows]), 'max_f1') for arm in ARMS}


def evaluate_rows(rows, thresholds, n_boot=10000):
    if not rows or any(r['split'] != 'test' for r in rows):
        raise ValueError('test rows only')
    pairs = [(f'{mode}/{kind}', f'UNIVERSAL/{kind}')
        for mode in R.MODES if mode != 'UNIVERSAL' for kind in KINDS]
    pairs += [(f'{mode}/{kind}', f'{mode}/rule')
        for mode in R.MODES for kind in F.KINDS]
    result = dict(rows=len(rows), genomes=sorted({r['genome_id'] for r in rows}),
        label_basis=dict(Counter(r['label_basis'] for r in rows)), policies={})
    for name, cuts in [('calibration_selected', {a: thresholds[a]['value'] for a in ARMS}),
                       ('fixed_0.5', {a: .5 for a in ARMS})]:
        result['policies'][name] = dict(
            arms={a: A.metrics(rows, a, cuts[a]) for a in ARMS},
            comparisons={f'{a}_vs_{b}': A.paired(rows, a, b, cuts, n_boot) for a, b in pairs})
    return result


def register(training, replay, out):
    protocol = R.verify(training)
    production = json.loads((replay / 'verification.json').read_text())
    if production.get('status') != 'verified' or production.get('schema') != 'gspa.observed-gap-context-model-verification/1':
        raise ValueError('complete verified context production replay required')
    F.check_hashes(production['inputs']); F.check_hashes(production['outputs'])
    frozen = json.loads((training / 'training.json').read_text())
    exported = json.loads((training / 'export.json').read_text())
    if frozen.get('status') != 'verified' or exported.get('status') != 'verified':
        raise ValueError('complete frozen models and exports required')
    F.check_hashes(frozen['outputs']); F.check_hashes(exported['outputs'])
    inputs = F.hashes(R.sources() + [replay / 'verification.json', training / 'training.json', training / 'export.json'])
    inputs.update(production['inputs']); inputs.update(production['outputs'])
    inputs.update(frozen['outputs']); inputs.update(exported['outputs'])
    plans = {}
    for transfer in R.G.MODES:
        table = training / transfer / 'UNIVERSAL/table/training_table.jsonl'
        for mode in R.MODES:
            R.compare_supervision(table, training / transfer / mode / 'table/training_table.jsonl', mode)
        paths = {}
        for mode in R.MODES:
            with Path(protocol['plans'][transfer][mode]['manifest']).open() as f:
                paths[f'{mode}/rule'] = {r['genome_id']: r['out_path'] for r in csv.DictReader(f, delimiter='\t')}
            for kind in F.KINDS:
                paths[f'{mode}/{kind}'] = {g: str(replay / transfer / mode / kind / 'inference' / (g + '.integrated.tsv')) for g in protocol['genomes']}
        if any(set(p) != set(protocol['genomes']) for p in paths.values()):
            raise ValueError('incomplete genome coverage')
        # Every consumed file must be among the verified artifacts, not merely
        # present beside them in a similarly named directory.
        consumed = [table] + [Path(p) for arm in paths.values() for p in arm.values()]
        if any(str(p.resolve()) not in inputs for p in consumed):
            raise ValueError('unverified analysis input')
        plans[transfer] = dict(table=str(table), paths=paths)
    out.mkdir(parents=True, exist_ok=False)
    A.save(out / 'protocol.json', dict(POLICY, plans=plans))
    A.save(out / 'registration.json', dict(status='registered',
        registered_at=F.datetime.now(F.timezone.utc).isoformat(),
        protocol_sha256=F.T.sha256_file(out / 'protocol.json'), inputs=inputs))


def run(out):
    reg = json.loads((out / 'registration.json').read_text()); F.check_hashes(reg['inputs'])
    if F.T.sha256_file(out / 'protocol.json') != reg['protocol_sha256']:
        raise ValueError('comparison protocol changed')
    protocol = json.loads((out / 'protocol.json').read_text())
    if any(protocol[k] != v for k, v in POLICY.items()):
        raise ValueError('analysis policy changed')
    if (out / 'thresholds.json').exists():
        raise FileExistsError('refusing analysis overwrite')
    prepared = {}; thresholds = {}
    for transfer, plan in protocol['plans'].items():
        with Path(plan['table']).open() as f:
            rows = [json.loads(s) for s in f]
        scores = {a: {g: A.read_scores(Path(p)) for g, p in paths.items()} for a, paths in plan['paths'].items()}
        prepared[transfer] = attach_scores(rows, scores)
        thresholds[transfer] = select_thresholds([r for r in prepared[transfer] if r['split'] == 'calibration'])
    A.save(out / 'thresholds.json', thresholds)
    threshold_hash = F.T.sha256_file(out / 'thresholds.json')
    results = {t: evaluate_rows([r for r in rows if r['split'] == 'test'], thresholds[t]) for t, rows in prepared.items()}
    A.save(out / 'results.json', dict(scope=__doc__, results=results))
    with (out / 'scored-supervision.jsonl').open('x') as f:
        for transfer, rows in prepared.items():
            for row in rows:
                f.write(json.dumps(dict(transfer=transfer, **row), allow_nan=False) + '\n')
    F.check_hashes(reg['inputs'])
    if F.T.sha256_file(out / 'thresholds.json') != threshold_hash or F.T.sha256_file(out / 'protocol.json') != reg['protocol_sha256']:
        raise ValueError('analysis policy changed during evaluation')
    A.save(out / 'verification.json', dict(status='verified', inputs=reg['inputs'], outputs=F.hashes([p for p in out.iterdir() if p.is_file()])))
    return results


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['register', 'run'])
    for key in ('training', 'replay', 'out'):
        parser.add_argument('--' + key, type=Path, required=key == 'out')
    args = parser.parse_args()
    if args.action == 'register':
        if not args.training or not args.replay:
            parser.error('training and replay required')
        register(args.training.resolve(), args.replay.resolve(), args.out.resolve())
    else:
        run(args.out.resolve())

"""Descriptive matched comparison of verified production outputs on frozen supervision.

This previously examined cohort measures reference-annotation support under its
closed-world policy. Unconfirmed rows are not experimentally proven negatives.
All test rows, including learned abstentions with rule fallback, remain included.
No model promotion, biological calibration, unseen-family or null claim is made.
"""
import argparse
from collections import Counter
import csv
import json
import math
from pathlib import Path
import sys

import fit_observed_gap_models as B
import v3_metrics as M
F=B.F
ARMS=('rule_no_gaps','rule_observed_gaps','logistic','gbdt')
POLICY=dict(schema='gspa.observed-gap-comparison/1',scope=__doc__,arms=list(ARMS),
    thresholds='Separate max-F1 thresholds from complete calibration rows; ties choose higher threshold. Also report common fixed 0.5.',
    population='All frozen test supervision rows within each transfer regime; no supported-only selection or cross-regime pooling.',
    bootstrap=dict(unit='paired genome',replicates=10000,seed=20261027),
    uncertainty='Descriptive percentile resampling of four previously examined test genomes; not a calibrated population confidence claim.')


def save(path,value):
    path.write_text(json.dumps(value,sort_keys=True,indent=2,allow_nan=False)+'\n')


def probability(value):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value) or not 0<=value<=1:
        raise ValueError('invalid probability')
    return value


def function_key(row):
    term=row['function_id'];kind=row['function_type']
    if kind=='EC' and term.startswith('EC:'):term=term[3:]
    return row['protein_id'],kind,term


def read_scores(path):
    result={}
    with path.open() as f:
        for row in csv.DictReader(f,delimiter='\t'):
            key=function_key(dict(row,function_type=row['type']))
            if key in result:raise ValueError('duplicate prediction identity')
            result[key]=probability(float(row['posterior_prob']))
    return result


def attach_scores(rows, by_arm):
    """Require all registered supervision identities, never silently intersect."""
    result=[];seen=set()
    if set(by_arm)!=set(ARMS):raise ValueError('missing comparison arm')
    for row in rows:
        if row['split'] not in ('train','calibration','test'):raise ValueError('unknown split')
        if type(row['label']) is not int or row['label'] not in (0,1):raise ValueError('invalid label')
        gid=row['genome_id'];key=function_key(row);identity=(gid,key)
        if identity in seen:raise ValueError('duplicate supervised function identity')
        seen.add(identity)
        scores={}
        for arm in ARMS:
            if gid not in by_arm[arm] or key not in by_arm[arm][gid]:raise ValueError('missing supervised prediction')
            scores[arm]=probability(by_arm[arm][gid][key])
        result.append(dict(example_id=row['example_id'],genome_id=gid,split=row['split'],
            label=row['label'],label_basis=row['label_basis'],scores=scores))
    return result


def select_thresholds(calibration):
    if not calibration or any(r['split']!='calibration' for r in calibration):
        raise ValueError('threshold selection requires calibration rows only')
    if {r['label'] for r in calibration}!={0,1}:raise ValueError('both calibration classes required')
    return {arm:F.T.choose_threshold(F.T.np.asarray([r['scores'][arm] for r in calibration]),
        F.T.np.asarray([r['label'] for r in calibration]),'max_f1') for arm in ARMS}


def metrics(rows,arm,threshold):
    if not rows:raise ValueError('empty evaluation population')
    bins=[[] for _ in range(10)];tp=fp=fn=tn=0;loss=0.
    for r in rows:
        p=probability(r['scores'][arm]);y=r['label'];call=p>=threshold
        tp+=call and y==1;fp+=call and y==0;fn+=not call and y==1;tn+=not call and y==0
        loss+=(p-y)**2;bins[min(int(p*10),9)].append((p,y))
    return dict(n=len(rows),positives=tp+fn,tp=tp,fp=fp,fn=fn,tn=tn,
        precision=tp/(tp+fp) if tp+fp else None,recall=tp/(tp+fn) if tp+fn else None,
        f1=2*tp/(2*tp+fp+fn) if 2*tp+fp+fn else None,
        brier=loss/len(rows),ece_10bin=sum(abs(sum(p-y for p,y in b)) for b in bins)/len(rows),
        threshold=threshold)


def paired(rows,arm,base,thresholds,n_boot=10000):
    vectors={};counts=Counter()
    for gid in sorted({r['genome_id'] for r in rows}):
        subset=[r for r in rows if r['genome_id']==gid];corrected=harmed=changed=0
        for r in subset:
            a=r['scores'][arm]>=thresholds[arm];b=r['scores'][base]>=thresholds[base]
            corrected+=a==r['label'] and b!=r['label'];harmed+=a!=r['label'] and b==r['label']
            changed+=a!=b
        delta=metrics(subset,arm,thresholds[arm])['brier']-metrics(subset,base,thresholds[base])['brier']
        vectors[gid]=[len(subset),delta,1,corrected,harmed,changed]
        counts.update(corrected=corrected,harmed=harmed,changed=changed)
    boot=M.genome_bootstrap(vectors,lambda v:v[1]/v[2],n_boot,POLICY['bootstrap']['seed'])
    # Undefined intervals are explicit nulls, never nonstandard JSON NaN.
    boot={k:(None if isinstance(v,float) and not math.isfinite(v) else v) for k,v in boot.items()}
    return dict(reference_corrected=counts['corrected'],reference_harmed=counts['harmed'],
        net_reference_corrections=counts['corrected']-counts['harmed'],changed_calls=counts['changed'],
        mean_genome_brier_delta=boot,per_genome={g:dict(rows=v[0],brier_delta=v[1],
        reference_corrected=v[3],reference_harmed=v[4],changed_calls=v[5]) for g,v in vectors.items()})


def evaluate_rows(test,thresholds,n_boot=10000):
    if not test or any(r['split']!='test' for r in test):raise ValueError('test rows only')
    result=dict(rows=len(test),genomes=sorted({r['genome_id'] for r in test}),
        label_basis=dict(Counter(r['label_basis'] for r in test)),policies={})
    for name,cuts in [('calibration_selected',{a:thresholds[a]['value'] for a in ARMS}),('fixed_0.5',{a:.5 for a in ARMS})]:
        result['policies'][name]=dict(arms={a:metrics(test,a,cuts[a]) for a in ARMS},comparisons={
            f'{arm}_vs_{base}':paired(test,arm,base,cuts,n_boot)
            for base in ('rule_no_gaps','rule_observed_gaps') for arm in ARMS if arm!=base})
    return result


def register(training,replay,out):
    fitting=B.verify(training);comparison=Path(fitting['comparison']);protocol=B.G.verify(comparison)
    production=json.loads((replay/'verification.json').read_text())
    if production.get('status')!='verified':raise ValueError('complete verified production replay required')
    F.check_hashes(production['inputs']);F.check_hashes(production['outputs'])
    export=json.loads((comparison/'verification.json').read_text());F.check_hashes(export['outputs'])
    sources=[Path(m.__file__).resolve() for m in tuple(sys.modules.values()) if getattr(m,'__file__',None)
        and Path(m.__file__).suffix=='.py' and Path(m.__file__).resolve().is_relative_to(F.ROOT)]
    inputs=F.hashes(sources+[replay/'verification.json',comparison/'verification.json',training/'training.json'])
    inputs.update(production['inputs']);inputs.update(production['outputs']);inputs.update(export['outputs'])
    plans={}
    for mode in B.G.MODES:
        table=training/mode/'default/table/training_table.jsonl';inputs.update(F.hashes([table]));paths={}
        for arm in ARMS:
            if arm.startswith('rule_'):
                manifest=Path(protocol['plans'][mode][arm[5:]]['manifest'])
                with manifest.open() as f:paths[arm]={r['genome_id']:r['out_path'] for r in csv.DictReader(f,delimiter='\t')}
            else:paths[arm]={gid:str(replay/mode/arm/'inference'/(gid+'.integrated.tsv')) for gid in protocol['genomes']}
            if set(paths[arm])!=set(protocol['genomes']):raise ValueError('incomplete genome coverage')
        plans[mode]=dict(table=str(table),paths=paths)
    out.mkdir(parents=True,exist_ok=False);save(out/'protocol.json',dict(POLICY,plans=plans))
    save(out/'registration.json',dict(status='registered',registered_at=F.datetime.now(F.timezone.utc).isoformat(),
        protocol_sha256=F.T.sha256_file(out/'protocol.json'),inputs=inputs))


def run(out):
    reg=json.loads((out/'registration.json').read_text());F.check_hashes(reg['inputs'])
    if F.T.sha256_file(out/'protocol.json')!=reg['protocol_sha256']:raise ValueError('comparison protocol changed')
    protocol=json.loads((out/'protocol.json').read_text())
    if any(protocol[k]!=v for k,v in POLICY.items()):raise ValueError('analysis policy changed')
    if (out/'thresholds.json').exists():raise FileExistsError('refusing analysis overwrite')
    prepared={};thresholds={}
    for mode,plan in protocol['plans'].items():
        with Path(plan['table']).open() as f:rows=[json.loads(s) for s in f]
        scores={a:{g:read_scores(Path(p)) for g,p in paths.items()} for a,paths in plan['paths'].items()}
        prepared[mode]=attach_scores(rows,scores)
        thresholds[mode]=select_thresholds([r for r in prepared[mode] if r['split']=='calibration'])
    # All policies are frozen before the first test metric is calculated.
    save(out/'thresholds.json',thresholds);threshold_hash=F.T.sha256_file(out/'thresholds.json')
    results={mode:evaluate_rows([r for r in rows if r['split']=='test'],thresholds[mode]) for mode,rows in prepared.items()}
    save(out/'results.json',dict(scope=__doc__,results=results))
    with (out/'scored-supervision.jsonl').open('x') as f:
        for mode,rows in prepared.items():
            for row in rows:f.write(json.dumps(dict(mode=mode,**row),allow_nan=False)+'\n')
    F.check_hashes(reg['inputs'])
    if F.T.sha256_file(out/'thresholds.json')!=threshold_hash:raise ValueError('thresholds changed during evaluation')
    if F.T.sha256_file(out/'protocol.json')!=reg['protocol_sha256']:raise ValueError('comparison protocol changed during evaluation')
    save(out/'verification.json',dict(status='verified',inputs=reg['inputs'],outputs=F.hashes([p for p in out.iterdir() if p.is_file()])))
    return results


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('action',choices=['register','run'])
    for k in ('training','replay','out'):p.add_argument('--'+k,type=Path,required=k=='out')
    a=p.parse_args()
    if a.action=='register':
        if not a.training or not a.replay:p.error('training and replay required')
        register(a.training.resolve(),a.replay.resolve(),a.out.resolve())
    else:run(a.out.resolve())

"""Audit every candidate from twelve frozen observed-gap context-mode models.

At most two independent arms run concurrently; each uses the registered JVM
limits and four Python audit workers. All commands are registered before any
execution. Unsupported fallback, taxonomy and supplied gaps remain explicit.
"""
import argparse,csv,json
from concurrent.futures import ThreadPoolExecutor,ProcessPoolExecutor,as_completed
from multiprocessing import get_context
from pathlib import Path
import sys
import run_observed_gap_context_modes as R
import check_family_excluded_models as C
F=R.F


def make_plans(protocol,training,out,source_files):
    plans={};inputs={}
    for transfer in R.G.MODES:
        plans[transfer]={}
        for mode in R.MODES:
            baseline=protocol['plans'][transfer][mode]
            with Path(baseline['manifest']).open() as f:
                r=csv.DictReader(f,delimiter='\t');fields=r.fieldnames;original=list(r)
            if len(original)!=len(protocol['genomes']) or {r['genome_id'] for r in original}!=set(protocol['genomes']):raise ValueError('baseline genome coverage differs')
            plans[transfer][mode]={}
            for kind in F.KINDS:
                arm=out/transfer/mode/kind;arm.mkdir(parents=True,exist_ok=False)
                inference=arm/'inference';inference.mkdir();manifest=arm/'manifest.tsv'
                with manifest.open('w') as f:
                    w=csv.DictWriter(f,fieldnames=fields,delimiter='\t',lineterminator='\n');w.writeheader()
                    w.writerows(dict(r,out_path=str(inference/(r['genome_id']+'.integrated.tsv'))) for r in original)
                model=training/transfer/mode/'models'/f'model_{kind}.json';command=list(baseline['command'])
                for flag,value in [('--batch-manifest',manifest),('--feature-export-dir',arm/'features'),
                    ('--batch-stats-out',inference/'batch_stats.tsv'),('--features-out',inference/'rlc-features.tsv'),
                    ('--suggestions-out',inference/'rlc-suggestions.tsv'),('--learned-model',model)]:F.replace(command,flag,value)
                F.save(arm/'command.json',command)
                inputs.update(F.V.describe_run(command,manifest,sources=source_files)['inputs']);inputs.update(F.hashes([arm/'command.json']))
                plans[transfer][mode][kind]=dict(arm=str(arm),manifest=str(manifest),command=command,inference=str(inference),
                    features=str(arm/'features'),model=str(model),baseline=baseline,original_rows=original)
    return plans,inputs


def audit_arm(transfer,mode,kind,plan,protocol,source_files):
    F.V.run_batch(plan['command'],Path(plan['manifest']),Path(plan['inference']),sources=source_files)
    summaries={}
    with ProcessPoolExecutor(max_workers=4,mp_context=get_context('spawn')) as pool:
        jobs=[]
        for row in plan['original_rows']:
            gid=row['genome_id'];current=Path(plan['inference'])/(gid+'.integrated.tsv')
            if R.G.R.canonical(R.G.R.jsonl(Path(str(current)+'.gaps.jsonl')))!=R.G.R.canonical(R.G.R.jsonl(Path(protocol['gaps'][gid]['path']))):raise ValueError('learned context run changed supplied gaps')
            jobs.append((gid,pool.submit(C.audit_genome,Path(row['out_path']),current,
                Path(plan['baseline']['features'])/gid/'candidate_features.jsonl',
                Path(plan['features'])/gid/'candidate_features.jsonl',Path(plan['model']))))
        for gid,future in jobs:summaries[gid]=future.result()
    F.save(Path(plan['arm'])/'audit.json',summaries)
    print(json.dumps(dict(transfer=transfer,mode=mode,model=kind,genomes=len(summaries),candidates=sum(s['candidates'] for s in summaries.values()))),flush=True)
    return summaries


def run(training,out):
    protocol=R.verify(training);frozen=json.loads((training/'training.json').read_text());export=json.loads((training/'export.json').read_text())
    if frozen.get('status')!='verified' or export.get('status')!='verified':raise ValueError('all frozen models and exports must be verified')
    F.check_hashes(frozen['outputs']);F.check_hashes(export['outputs'])
    for transfer in R.G.MODES:
        for mode in R.MODES:
            for kind in F.KINDS:
                if str((training/transfer/mode/'models'/f'model_{kind}.json').resolve()) not in frozen['outputs']:raise ValueError('missing frozen model')
    out.mkdir(parents=True,exist_ok=False);source_files=R.sources()
    plans,inputs=make_plans(protocol,training,out,source_files)
    inputs.update(F.hashes([training/'protocol.json',training/'registration.json',training/'export.json',training/'training.json']))
    inputs.update(json.loads((training/'registration.json').read_text())['inputs']);inputs.update(export['outputs']);inputs.update(frozen['outputs'])
    F.save(out/'registration.json',dict(status='registered',registered_at=F.datetime.now(F.timezone.utc).isoformat(),
        scope=__doc__,plans=plans,inputs=inputs,max_concurrent_arms=2,audit_workers_per_arm=4))
    summaries={t:{m:{} for m in R.MODES} for t in R.G.MODES}
    with ThreadPoolExecutor(max_workers=2) as pool:
        jobs={pool.submit(audit_arm,t,m,k,p,protocol,source_files):(t,m,k) for t,modes in plans.items() for m,kinds in modes.items() for k,p in kinds.items()}
        try:
            for future in as_completed(jobs):
                t,m,k=jobs[future];summaries[t][m][k]=future.result()
        except BaseException:
            for future in jobs:future.cancel()
            raise
    F.check_hashes(inputs);R.verify(training)
    result=dict(status='verified',schema='gspa.observed-gap-context-model-verification/1',scope=__doc__,
        genomes=len(protocol['genomes']),summaries=summaries,inputs=inputs,outputs=F.hashes([p for p in out.rglob('*') if p.is_file()]))
    F.save(out/'verification.json',result)
    return result


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for k in ('training','out'):p.add_argument('--'+k,type=Path,required=True)
    a=p.parse_args();r=run(a.training.resolve(),a.out.resolve());print(json.dumps({k:r[k] for k in ('schema','status','genomes')}))

"""Matched context-mode exports and refits with complete observed gap inputs.

All 18 genomes, both transfer regimes and all 521 observed gaps remain included.
This reused, reference-overlapping cohort has sparse gap-linked supervision; it
cannot establish biological accuracy or unseen-family missing-enzyme recovery.
All twelve models are frozen before any test evaluation. No model is promoted.
"""
import argparse
from collections import Counter
import copy,csv,itertools,json,math
from numbers import Real
from pathlib import Path
import sys
import fit_observed_gap_models as B
F=B.F
G=B.G
MODES=('UNIVERSAL','PATHWAY','ORGANISM')
CONTROLS=('default',)+MODES


def sources():
    return [Path(m.__file__).resolve() for m in tuple(sys.modules.values())
        if getattr(m,'__file__',None) and Path(m.__file__).suffix=='.py'
        and Path(m.__file__).resolve().is_relative_to(F.ROOT)]


def make_plans(protocol,context,jar,out,source_files):
    plans={};inputs={}
    for transfer in G.MODES:
        baseline=protocol['plans'][transfer]['observed_gaps']
        with Path(baseline['manifest']).open() as f:
            r=csv.DictReader(f,delimiter='\t');fields=r.fieldnames;original=list(r)
        if len(original)!=len(protocol['genomes']) or {r['genome_id'] for r in original}!=set(protocol['genomes']):
            raise ValueError('baseline genome coverage differs')
        base=baseline['command']
        if '--cohort' not in base or '--rlc-suggester' not in base or '--learned-model' in base:
            raise ValueError('observed-gap unscored joint-cohort baseline required')
        for row in original:
            if row['gaps_path']!=protocol['gaps'][row['genome_id']]['path']:
                raise ValueError('baseline lacks the registered observed gaps')
        plans[transfer]={}
        for mode in CONTROLS:
            arm=out/transfer/mode;arm.mkdir(parents=True,exist_ok=False)
            inference=arm/'inference';inference.mkdir();manifest=arm/'manifest.tsv'
            rows=[dict(r,out_path=str(inference/(r['genome_id']+'.integrated.tsv'))) for r in original]
            with manifest.open('w') as f:
                w=csv.DictWriter(f,fieldnames=fields,delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(rows)
            command=list(base)
            for flag,value in [('-jar',jar),('--batch-manifest',manifest),('--feature-export-dir',arm/'features'),
                ('--batch-stats-out',inference/'batch_stats.tsv'),('--features-out',inference/'rlc-features.tsv'),
                ('--suggestions-out',inference/'rlc-suggestions.tsv')]:F.replace(command,flag,value)
            if mode!='default':
                for flag,value in [('--cohort-context-mode',mode),('--cohort-pathways',context/'pathway-groups.tsv'),
                    ('--cohort-metadata',context/'organism-metadata.json')]:F.replace(command,flag,value)
            F.save(arm/'command.json',command)
            inputs.update(F.V.describe_run(command,manifest,sources=source_files)['inputs'])
            inputs.update(F.hashes([arm/'command.json']))
            plans[transfer][mode]=dict(arm=str(arm),features=str(arm/'features'),inference=str(inference),
                manifest=str(manifest),command=command,baseline=baseline)
    return plans,inputs


def compare_features(before,after,mode,exact=False):
    changes=Counter();seen=set()
    with before.open() as a,after.open() as b:
        for left,right in itertools.zip_longest(a,b):
            if left is None or right is None:raise ValueError('candidate coverage changed')
            x,y=json.loads(left),json.loads(right)
            for key in ('candidate_key','genome_id','protein_id','function_type','function_id','role',
                'sequence_sources','sequence_contracts','quality_evidence'):
                if x.get(key)!=y.get(key):raise ValueError('candidate identity or provenance changed: '+key)
            if y['candidate_key'] in seen:raise ValueError('duplicate candidate')
            seen.add(y['candidate_key'])
            expected=mode if y['features']['cohort.w.ec_direct'] else 'UNIVERSAL'
            if y['cohort_context_mode']!=expected:raise ValueError('wrong candidate context mode')
            if x['features'].keys()!=y['features'].keys():raise ValueError('feature contract changed')
            for name,value in x['features'].items():
                if any(isinstance(v,bool) or not isinstance(v,Real) or not math.isfinite(v) for v in (value,y['features'][name])):
                    raise ValueError('nonfinite or invalid context feature')
                if value!=y['features'][name]:
                    if exact or not name.startswith('cohort.'):raise ValueError('non-context feature changed: '+name)
                    changes[name]+=1
            if x['features']['ctx.gap.available']!=1 or y['features']['ctx.gap.available']!=1:
                raise ValueError('observed gaps unavailable')
    return dict(candidates=len(seen),changed_columns=dict(changes))


def compare_supervision(before,after,mode):
    n=0
    with before.open() as a,after.open() as b:
        for left,right in itertools.zip_longest(a,b):
            if left is None or right is None:raise ValueError('supervision coverage changed')
            old,new=json.loads(left),json.loads(right)
            expected=mode if new['features']['cohort.w.ec_direct'] else 'UNIVERSAL'
            if new['cohort_context_mode']!=expected:raise ValueError('wrong supervised context mode')
            for row in (old,new):row.pop('features');row.pop('cohort_context_mode',None)
            if old!=new:raise ValueError('supervision identity, split, label, role or source changed')
            n+=1
    return n


def supervision_inputs(recipes, reference_inputs):
    """Carry the frozen fit's data dependencies into the new registration.

    Binding the parent registration file alone does not stage or verify its
    referenced labels, split registry, ontology and locus/family declarations.
    Every recipe input must retain its previously registered bytes.
    """
    required = {str(Path(value).resolve()) for recipe in recipes.values()
                for value in recipe['supervision'].values() if value}
    missing = required - reference_inputs.keys()
    if missing:
        raise ValueError('unregistered supervision inputs: ' + ', '.join(sorted(missing)))
    bound = {path: reference_inputs[path] for path in sorted(required)}
    F.check_hashes(bound)
    return bound


def prepare(training,context,jar,out):
    fitting=B.verify(training);frozen=json.loads((training/'training.json').read_text())
    if frozen.get('status')!='verified':raise ValueError('verified reference training required')
    F.check_hashes(frozen['outputs'])
    comparison=Path(fitting['comparison']);base=G.verify(comparison)
    exported=json.loads((comparison/'verification.json').read_text())
    if exported.get('status')!='verified':raise ValueError('complete observed-gap export required')
    F.check_hashes(exported['inputs']);F.check_hashes(exported['outputs'])
    receipt=json.loads((context/'receipt.json').read_text())
    if receipt.get('status')!='verified' or receipt['genomes']!=len(base['genomes']):raise ValueError('complete verified context acquisition required')
    F.check_hashes(receipt['inputs']);F.check_hashes({str(context/k):v for k,v in receipt['outputs'].items()})
    meta=json.loads((context/'organism-metadata.json').read_text())
    if set(meta['genomes'])!=set(base['genomes']):raise ValueError('context metadata genome coverage differs')
    out.mkdir(parents=True,exist_ok=False)
    plans,inputs=make_plans(base,context,jar,out,sources())
    inputs.update(F.hashes([training/'training.json',training/'protocol.json',training/'registration.json',
        comparison/'verification.json',context/'receipt.json']))
    inputs.update(frozen['outputs']);inputs.update(exported['inputs']);inputs.update(exported['outputs'])
    inputs.update(receipt['inputs']);inputs.update({str(context/k):v for k,v in receipt['outputs'].items()})
    recipes=copy.deepcopy(fitting['recipes'])
    for transfer in G.MODES:recipes[transfer]['original_table']=str(training/transfer/'default/table/training_table.jsonl')
    parent_registration=json.loads((training/'registration.json').read_text())
    inputs.update(supervision_inputs(recipes,parent_registration['inputs']))
    protocol=dict(schema='gspa.observed-gap-context-modes/1',scope=__doc__,plans=plans,recipes=recipes,
        modes=list(MODES),controls=list(CONTROLS),transfers=list(G.MODES),genomes=base['genomes'],gaps=base['gaps'],
        claims=base['claims'],contracts=base['contracts'],python_version=sys.version,numpy_version=F.T.np.__version__,
        comparison=str(comparison),context_inputs=str(context),labels_read_for_export=False,model_promotion='none')
    F.save(out/'protocol.json',protocol)
    F.save(out/'registration.json',dict(status='registered',registered_at=F.datetime.now(F.timezone.utc).isoformat(),
        protocol_sha256=F.T.sha256_file(out/'protocol.json'),inputs=inputs))
    return verify(out)


def verify(out):
    reg=json.loads((out/'registration.json').read_text());F.check_hashes(reg['inputs'])
    if F.T.sha256_file(out/'protocol.json')!=reg['protocol_sha256']:raise ValueError('registered context protocol changed')
    p=json.loads((out/'protocol.json').read_text())
    supervision_inputs(p['recipes'],reg['inputs'])
    if p['python_version']!=sys.version or p['numpy_version']!=F.T.np.__version__ or p['modes']!=list(MODES) or p['controls']!=list(CONTROLS) or p['transfers']!=list(G.MODES):
        raise ValueError('registered runtime or comparison scope changed')
    return p


def export(out):
    p=verify(out)
    if (out/'export.json').exists():raise FileExistsError('export refuses overwrite')
    summaries={}
    for transfer in G.MODES:
        summaries[transfer]={}
        for mode in CONTROLS:
            plan=p['plans'][transfer][mode];arm=Path(plan['arm'])
            F.V.run_batch(plan['command'],Path(plan['manifest']),Path(plan['inference']),sources=sources())
            counts=F.audit_export(Path(plan['features']),p['claims'][transfer],p['contracts'][transfer])
            if set(counts)!=set(p['genomes']):raise ValueError('export genome coverage differs')
            reference=plan['baseline'] if mode=='default' else p['plans'][transfer]['default' if mode=='UNIVERSAL' else 'UNIVERSAL']
            by_genome={}
            for gid in p['genomes']:
                before=Path(reference['inference'])/(gid+'.integrated.tsv');after=Path(plan['inference'])/before.name
                if mode=='default' and F.T.sha256_file(before)!=F.T.sha256_file(after):raise ValueError('new-engine control changed functional predictions')
                r=compare_features(Path(reference['features'])/gid/'candidate_features.jsonl',
                    Path(plan['features'])/gid/'candidate_features.jsonl','UNIVERSAL' if mode=='default' else mode,exact=mode=='default')
                if G.R.canonical(G.R.jsonl(Path(str(after)+'.gaps.jsonl')))!=G.R.canonical(G.R.jsonl(Path(p['gaps'][gid]['path']))):raise ValueError('observed gap records changed')
                r.update(functional_changes=G.compare_predictions(before,after,arm/(gid+'.prediction-changes.tsv')),
                    gaps=p['gaps'][gid]['records'],rlc_rows=len(G.R.rows(Path(str(after)+'.features.tsv'))),
                    suggestions=len(G.R.rows(Path(str(after)+'.suggestions.tsv'))))
                by_genome[gid]=r
            summaries[transfer][mode]=by_genome;F.save(arm/'comparison.json',by_genome)
            print(json.dumps(dict(transfer=transfer,mode=mode,genomes=len(by_genome),candidates=sum(r['candidates'] for r in by_genome.values()))),flush=True)
    verify(out);F.save(out/'export.json',dict(status='verified',summaries=summaries,
        outputs=F.hashes([q for q in out.rglob('*') if q.is_file()])))


def train(out):
    p=verify(out);e=json.loads((out/'export.json').read_text())
    if e.get('status')!='verified':raise ValueError('complete verified context exports required')
    F.check_hashes(e['outputs'])
    if any((out/t/m/'table').exists() or (out/t/m/'models').exists() for t in G.MODES for m in MODES):raise FileExistsError('training refuses overwrite')
    counts={};outputs=[]
    for transfer in G.MODES:
        recipe=p['recipes'][transfer];inputs=recipe['supervision'];counts[transfer]={}
        for mode in MODES:
            arm=out/transfer/mode;features=arm/'features';contract_path=next(features.glob('*/feature_contract.json'))
            table=F.P.build_table(features,contract_path,Path(inputs['labels']),Path(inputs['splits']),
                Path(inputs['label_policy']),arm/'table',registry_path=Path(inputs['registry']),go_obo=inputs['go_obo'],
                example_clusters=inputs['example_clusters'],locus_groups=inputs.get('locus_groups'),disjoint=tuple(recipe['disjoint_keys']))
            preserved=compare_supervision(Path(recipe['original_table']),Path(table['table']),mode)
            contract=F.T.load_contract(contract_path);rows=F.T.read_table(Path(table['table']),contract);F.T.check_disjoint(rows,['group','genome_id'])
            splits={s:[r for r in rows if r['split']==s] for s in F.T.SPLITS};(arm/'models').mkdir()
            for kind in F.KINDS:
                model=arm/'models'/f'model_{kind}.json'
                artifact=F.T.train(splits['train'],splits['calibration'],contract,kind,**recipe['settings'][kind],identity=F.T.split_identity(rows,['group','genome_id']))
                F.T.write_frozen(artifact,model);outputs.append(model)
            outputs.extend([Path(table['table']),arm/'table/training_table_manifest.json'])
            counts[transfer][mode]=dict(supervision_rows_preserved=preserved,rows_by_split={s:len(v) for s,v in splits.items()})
    verify(out);F.check_hashes(e['outputs'])
    F.save(out/'training.json',dict(status='verified',frozen_at=F.datetime.now(F.timezone.utc).isoformat(),counts=counts,outputs=F.hashes(outputs)))


def evaluate(out):
    p=verify(out)
    if (out/'evaluation.json').exists():raise FileExistsError('evaluation refuses overwrite')
    frozen=json.loads((out/'training.json').read_text())
    if frozen.get('status')!='verified':raise ValueError('all twelve models must be frozen')
    F.check_hashes(frozen['outputs'])
    for transfer in G.MODES:
        for mode in MODES:
            for kind in F.KINDS:
                if str((out/transfer/mode/'models'/f'model_{kind}.json').resolve()) not in frozen['outputs']:raise ValueError('missing frozen model')
    results={}
    for transfer in G.MODES:
        results[transfer]={}
        for mode in MODES:
            arm=out/transfer/mode;table=arm/'table/training_table.jsonl'
            contract=F.T.load_contract(next((arm/'features').glob('*/feature_contract.json')))
            rows=[r for r in F.T.read_table(table,contract) if r['split']=='test'];results[transfer][mode]={}
            for kind in F.KINDS:
                model=arm/'models'/f'model_{kind}.json'
                results[transfer][mode][kind]=F.T.evaluate_frozen(model,contract,rows,F.T.sha256_file(model),F.T.sha256_file(table))
    verify(out);F.check_hashes(frozen['outputs']);F.save(out/'evaluation.json',results)


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('action',choices=['prepare','export','train','evaluate']);p.add_argument('--out',type=Path,required=True)
    for k in ('training','context','jar'):p.add_argument('--'+k,type=Path)
    a=p.parse_args()
    if a.action=='prepare':
        if not all((a.training,a.context,a.jar)):p.error('training, context and jar required')
        prepare(a.training.resolve(),a.context.resolve(),a.jar.resolve(),a.out.resolve())
    else:globals()[a.action](a.out.resolve())

